 /// How many entries move between memory and storage per statement batch.
 const BATCH: usize = 1024;

+/// Bound SQL compilation and parameter storage independently of blocking jobs.
+const MEMBERSHIP_BATCH: usize = 256;
+
+fn membership_batch_sql(width: usize) -> &'static str {
+    // Nine power-of-two shapes keep the prepared cache bounded. NULL padding
+    // never satisfies equality with an encoded spill key.
+    static QUERIES: std::sync::LazyLock<Vec<String>> = std::sync::LazyLock::new(|| {
+        (0..=MEMBERSHIP_BATCH.trailing_zeros())
+            .map(|power| {
+                let values = (0..1usize << power)
+                    .map(|index| format!("({index}, ?{})", index + 1))
+                    .collect::<Vec<_>>()
+                    .join(",");
+                format!(
+                    "WITH requested(ordinal, key) AS (VALUES {values}) \
+                     SELECT requested.ordinal FROM requested \
+                     JOIN entries ON entries.key = requested.key"
+                )
+            })
+            .collect()
+    });
+    &QUERIES[width.next_power_of_two().trailing_zeros() as usize]
+}
